-- Import des courriers arrivées 2015
-- Source : 2015.xlsx (feuille 2015).
--
-- Correspondance Excel -> table arrivees (formulaire arrivee/create.vue)
--   N° ARRIVEES            -> txt_numdordre (00001/jj-mm-aaaa)
--   DATE CREATION          -> dt_datearrivee
--   REFERENCE              -> txt_reference ; N° et date du courrier extraits
--   PRENOMS + NOMS         -> txt_prenomNom et txt_expediteur
--   objet                  -> txt_objet (libellé d'origine)
--   objet                  -> txt_designation (liste designationsParCategorie)
--   designation retenue    -> txt_categorie
--   N° TF                  -> txt_numTitreFoncier
--   ANCIEN N° TF           -> txt_numTitreMere
--   N° LOT                 -> txt_numLot
--   SITUATION/LOTISSEMENT  -> txt_lotissement
--   AGENTS TRAITEURS       -> txt_agenttraiteur
--   OBSERVATIONS           -> txt_observation
--   N° BE                  -> txt_numbordereau
--   DATE DEPART / AVIS     -> ajoutés à txt_observation
--   NICAD cité dans l'objet -> txt_NICAD
--
-- Champs obligatoires absents du classeur :
--   txt_typecourrier = BE si l'objet commence par « BE », sinon Individuel
--   txt_nombrepiece  = 1
--   expéditeur ou agent vide -> Non renseigné
-- Référence absente : « <N°> du jj-mm-aaaa », comme le formulaire.
-- Références en doublon : suffixe [n° d'ordre].
-- N° d'arrivée en doublon : suffixe -2, -3…
-- Lignes importées : 2109
-- Lignes non importées :
--   ligne Excel 2111 : date absente (N° 953)
--
-- Répartition des catégories :
--    1950  Demande SERVICES
--      95  Information
--      56  Convocation - Invitation
--       4  Réclamation - Signalement
--       4  Réquisition - Instruction
-- Désignations :
--     624  Demande de Régularisation par voie de Bail
--     620  Morcellements
--     270  Demande de Cession définitive
--      99  Demande de situation foncière
--      77  Demande d'états des lieux
--      75  Demande de délimitation
--      49  Autorisation de construction
--      44  Transmission lettre
--      35  Demande de terrain/Echange
--      32  Réunion
--      20  Autorisation de lotir
--      17  Formation
--      16  Duplication de CIC
--      16  Document administratif
--      13  Demande d'évaluation
--      13  Demande d'extraits de plan
--      12  Réquisition d'immatriculation
--       9  Note de service
--       9  Décision - Arrêté
--       8  Litiges
--       7  PV - Compte - rendu
--       7  Réceptions de lotissements
--       7  Tribunal
--       5  Autres
--       4  Rapport
--       4  Plainte
--       4  Instruction à suivre
--       3  Demande de Titre foncier
--       3  Cérémonie
--       3  Visite de site
--       1  Demande de CIC
--       1  Demande d'attestation du Cadastre
--       1  Circulaire
--       1  Session

SET NAMES utf8mb4;

START TRANSACTION;







COMMIT;
